'use strict';
const main=document.querySelector('main');
const KEY='eng101-studio-v1';
const ACTIVITY_INDEX=new Map([
  ...MCQS.map(item=>[item.id,{item,kind:'mcq'}]),
  ...EXERCISES.map(item=>[item.id,{item,kind:'code'}]),
  ...PROGRAMS.map(item=>[item.id,{item,kind:'program'}]),
  ...DEBUG_CASES.map(item=>[item.id,{item,kind:'debug'}])
]);
let storageOK=true;
function fresh(){return {records:{},revealed:[],started:Date.now()};}
function restoreSession(saved){
  const restored=fresh();
  if(!saved||typeof saved!=='object'||Array.isArray(saved))return restored;
  if(Number.isFinite(saved.started)&&saved.started>0)restored.started=saved.started;
  if(saved.records&&typeof saved.records==='object'&&!Array.isArray(saved.records)){
    for(const [id,r] of Object.entries(saved.records)){
      const entry=ACTIVITY_INDEX.get(id);
      if(!entry||!r||typeof r.firstCorrect!=='boolean'||typeof r.latestCorrect!=='boolean')continue;
      const {item,kind}=entry;
      restored.records[id]={firstCorrect:r.firstCorrect,latestCorrect:r.latestCorrect,attempts:Number.isInteger(r.attempts)&&r.attempts>0?r.attempts:1,title:kind==='mcq'?item.title:item.name,topic:item.topic,kind,time:Number.isFinite(r.time)?r.time:0};
    }
  }
  if(Array.isArray(saved.revealed))restored.revealed=[...new Set(saved.revealed.filter(id=>ACTIVITY_INDEX.has(id)))];
  for(const [key,kind] of [['codeDrafts','code'],['debugDrafts','debug']]){
    if(saved[key]&&typeof saved[key]==='object'&&!Array.isArray(saved[key])){
      restored[key]=Object.fromEntries(Object.entries(saved[key]).filter(([id,text])=>ACTIVITY_INDEX.get(id)?.kind===kind&&typeof text==='string'));
    }
  }
  return restored;
}
let state=fresh();
try {const saved=sessionStorage.getItem(KEY);if(saved){try{state=restoreSession(JSON.parse(saved));}catch{/* Discard damaged JSON while keeping storage available. */}}}catch{storageOK=false;}
