const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{sessionStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}}
function stats(){const valid=new Set([...MCQS,...EXERCISES,...PROGRAMS,...DEBUG_CASES].map(x=>x.id));const a=Object.entries(state.records).filter(([id])=>valid.has(id)).map(([,r])=>r);return {done:a.length,mcq:MCQS.filter(q=>state.records[q.id]).length,code:EXERCISES.filter(e=>state.records[e.id]?.latestCorrect).length,programs:PROGRAMS.filter(p=>state.records[p.id]?.latestCorrect).length,debug:DEBUG_CASES.filter(e=>state.records[e.id]?.latestCorrect).length,first:a.filter(r=>r.firstCorrect).length,missed:a.filter(r=>!r.latestCorrect).length};}
function record(item,correct,kind){let old=state.records[item.id];state.records[item.id]={firstCorrect:old?old.firstCorrect:correct,latestCorrect:correct,attempts:(old?.attempts||0)+1,title:kind==='mcq'?item.title:item.name,topic:item.topic,kind,time:Date.now()};save();}
