function paint(html,page,focus=true){main.innerHTML=(!storageOK?'<p class="storage-note">Session storage is unavailable. Progress will last until this page is reloaded.</p>':'')+html;setActive(page);if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}
