function home(){paint(`<div class="intro"><span class="eyebrow">TOPIC PRACTICE · WEEKS 1–6</span><h1>Focus on one Python idea.</h1><p>${collectionCounts().first} foundation MCQs across ${TOPICS.length} topics. Choose a short sample or a complete topic, then use the explanation to check your reasoning.</p><div class="actions"><button class="primary" data-mixed>Start a mixed foundation round →</button><a class="secondary" href="#banks/weeks-7-14">Practise Weeks 7–14 →</a></div></div><section><div class="section-heading"><div><h2>Choose a topic</h2><p>Build confidence with a focused round.</p></div><label class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Find a topic…" aria-label="Find a topic"></label></div><div class="topic-grid" id="topic-grid">${TOPICS.map(topicCard).join('')}</div><p id="no-results" class="empty" hidden>No topics match. Try “loops” or “lists”.</p></section><section class="collection-banner"><div><h2>Put the idea into code</h2><p>Move from reading a question to completing a short program.</p></div><a class="secondary" href="#code">Explore ${EXERCISES.length} guided exercises →</a></section>`,'practice');}
function startQuiz(ids,label,returnTo){if(!ids.length)return;const origin=location.hash.slice(1);returnTo=returnTo||(ids.every(id=>SECOND_HALF_MCQS.some(q=>q.id===id))?'banks/weeks-7-14':origin==='banks/weeks-1-6'||origin==='first-half'?'banks/weeks-1-6':origin.startsWith('topic/')?origin:'practice');run={ids,label,index:0,results:[],returnTo};selected=null;checked=false;nav('quiz');if(location.hash==='#quiz')quiz();}
