function quiz(){if(!run){nav('practice');return;}const item=MCQS.find(q=>q.id===run.ids[run.index]);const t=topicOf(item.topic);const correct=selected===item.answer;const back=quizReturn();paint(`<button class="back-button" data-nav="${back.page}">← ${back.label}</button><div class="question-layout"><section class="question-card"><div class="question-label"><span>${esc(run.label)} <span aria-hidden="true">/</span> ${t.name}</span><span>${run.index+1} of ${run.ids.length}</span></div><div class="progress-track"><span style="width:${run.index/run.ids.length*100}%"></span></div><span class="eyebrow">${item.source?esc(item.source):'STUDIO ORIGINAL'}</span><h1>${esc(item.title)}</h1>${item.note?`<p class="code-info">${esc(item.note)}</p>`:''}${item.code?`<pre><code>${esc(item.code)}</code></pre>`:''}<fieldset class="options"><legend class="skip">Choose one answer</legend>${item.options.map((o,i)=>`<label class="option ${checked&&i===item.answer?'correct':''} ${checked&&i===selected&&!correct?'wrong':''}"><input type="radio" name="answer" value="${i}" ${selected===i?'checked':''} ${checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span><span>${esc(o)}</span>${checked&&i===item.answer?'<span class="result-mark">✓ Correct</span>':''}${checked&&i===selected&&!correct?'<span class="result-mark">Your choice</span>':''}</label>`).join('')}</fieldset>${checked?`<div class="feedback ${correct?'':'incorrect'}" role="status"><h3>${correct?'✓ You’ve got it.':'A useful thing to learn.'}</h3><p>${esc(item.explanation)}</p><p class="correct-choice">Correct choice: ${'ABCD'[item.answer]} · ${esc(item.options[item.answer])}</p>${!correct&&item.why?.[selected]?`<p class="muted">Your choice: ${esc(item.why[selected])}</p>`:''}</div>`:''}<div class="question-actions"><span class="muted">${checked?'First attempts stay in your session stats.':'Take your time. There’s no timer.'}</span>${checked?`<button class="primary" id="next-question">${run.index+1===run.ids.length?'See practice summary':'Next question'} <span aria-hidden="true">→</span></button>`:`<button class="primary" id="check-answer" ${selected===null?'disabled':''}>Check answer <span aria-hidden="true">↗</span></button>`}</div></section><aside><div class="tip-panel"><span class="topic-icon" aria-hidden="true">${t.icon}</span><h3>A quick reminder</h3><p>${t.tip}</p><small>Make a prediction before you check.</small></div><div class="queue"><strong>Your practice, your pace.</strong><span>${run.ids.length} practice questions<br>Immediate explanations<br>Progress saved in this tab</span></div></aside></div>`,back.section);}
function summary(){if(!run){nav('practice');return;}let n=run.results.filter(Boolean).length;const back=quizReturn();paint(`<section class="summary-card"><div class="summary-icon" aria-hidden="true">↗</div><span class="eyebrow">${esc(run.label.toUpperCase())} COMPLETE</span><h1>Keep building on it.</h1><p class="muted">${n===run.ids.length?'A strong round. Try a little code to put it into practice.':'Each explanation gives you something to use next time.'}</p><div class="summary-score">${n} / ${run.ids.length} <small>correct this round</small></div><div class="actions"><button class="primary" data-nav="session">View my session</button><button class="secondary" data-nav="${back.page}">Back to ${back.label}</button></div></section>`,back.section);}
// Compare Python-like tokens, not whitespace-stripped text. Token boundaries matter:
// "if temperature" is valid, while "iftemperature" and "> =" are not equivalent.
function normalizeCode(s){
  const source=s.trim(),tokens=[];
  if(/[\r\n]/.test(source))return null; // These guided exercises request one line.
  for(let i=0;i<source.length;){
    const c=source[i];
    if(/[ \t\f]/.test(c)){i++;continue;}
    if(c==='"'||c==="'"){
      const quote=c;let value='',closed=false;i++;
      while(i<source.length){
        const ch=source[i++];
        if(ch==='\\'&&i<source.length){value+=ch+source[i++];continue;}
        if(ch===quote){closed=true;break;}
        value+=ch;
      }
      if(!closed)return null;
      tokens.push(['string',value]);continue;
    }
    const rest=source.slice(i);
    const name=rest.match(/^[A-Za-z_][A-Za-z0-9_]*/);
    if(name){tokens.push(['name',name[0]]);i+=name[0].length;continue;}
    const number=rest.match(/^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?/);
    if(number){tokens.push(['number',number[0]]);i+=number[0].length;continue;}
    const operator=rest.match(/^(?:\*\*=|\/\/=|<<=|>>=|:=|==|!=|<=|>=|\+=|-=|\*=|\/=|%=|&=|\|=|\^=|\*\*|\/\/|<<|>>|->|[+\-*\/%<>=:(),.\[\]{}~^&|;])/);
    if(!operator)return null;
    tokens.push(['operator',operator[0]]);i+=operator[0].length;
  }
  return JSON.stringify(tokens);
}
function session(){const s=stats();const rate=s.done?Math.round(s.first/s.done*100)+'%':'—';const recent=Object.values(state.records).sort((a,b)=>b.time-a.time).slice(0,6);paint(`<div class="intro"><span class="eyebrow">LOOK HOW FAR YOU’VE COME</span><h1>Your learning, this session.</h1><p>Progress lives in this browser tab and survives a refresh. It is practice feedback, separate from your course grade, and is not submitted to Moodle or synced across devices.</p></div><section class="collection-banner"><div><h2>${s.programs} / ${PROGRAMS.length} program outputs checked</h2><p>Program predictions count as activities. Viewing a solution alone does not count as solving it.</p></div><button class="secondary" data-nav="programs">Continue program studies →</button></section><section class="collection-banner"><div><h2>${s.debug} / ${DEBUG_CASES.length} debugging exercises repaired</h2><p>Code drafts stay in this tab. Viewing a repair alone does not mark it as solved.</p></div><button class="secondary" data-nav="debugging">Continue debugging →</button></section><div class="stat-cards"><div class="stat-card"><strong>${s.mcq}<small> / ${MCQS.length}</small></strong><span>MCQs attempted</span></div><div class="stat-card"><strong>${s.code}<small> / ${EXERCISES.length}</small></strong><span>Guided exercises solved</span></div><div class="stat-card"><strong>${rate}</strong><span>Correct on first submission</span></div><div class="stat-card"><strong>${s.missed}</strong><span>Activities to revisit</span></div></div><div class="two-col"><section class="panel"><h2>Weeks 1–6 · Topic progress</h2>${TOPICS.map(t=>`<div class="progress-row"><div><span>${t.name}</span><span>${doneTopic(t.id)} / ${MCQS.filter(q=>q.topic===t.id).length} MCQs</span></div><div class="progress-track"><span style="width:${doneTopic(t.id)/MCQS.filter(q=>q.topic===t.id).length*100}%"></span></div></div>`).join('')}<h2 class="progress-section">Weeks 7–14 · Weekly progress</h2>${SECOND_HALF_WEEKS.map(w=>{const qs=SECOND_HALF_MCQS.filter(q=>q.week===w.week),done=qs.filter(q=>state.records[q.id]).length;return `<div class="progress-row"><div><span>Week ${w.week} · ${esc(w.name)}</span><span>${done} / ${qs.length} MCQs</span></div><div class="progress-track"><span style="width:${done/qs.length*100}%"></span></div></div>`;}).join('')}<button class="primary" id="review-missed" ${s.missed?'':'disabled'}>Revisit missed activities <span aria-hidden="true">→</span></button></section><section class="panel"><h2>Recent practice</h2>${recent.length?recent.map(r=>`<div class="activity"><span aria-hidden="true">${r.latestCorrect?'✓':'↻'}</span><div>${esc(r.title)}<small>${r.kind==='mcq'?'MCQ':r.kind==='program'?'Program study':r.kind==='debug'?'Debugging':'Code lab'} · ${topicOf(r.topic).name} · ${r.latestCorrect?'Understood':'Keep practising'}</small></div></div>`).join(''):'<p class="empty">Your story starts with a single attempt. Choose any topic to begin.</p>'}<div class="callout"><p class="code-info">First-submission accuracy counts each attempted activity once. Retries update what needs revisiting, but don’t rewrite your first attempt.</p></div><div class="actions"><button class="secondary" data-nav="banks">Choose a practice set</button><button class="text-button" id="reset-session">Reset session</button></div></section></div>`,'session');}
function guide(){const c=collectionCounts();const scope=[['banks/weeks-1-6','Weeks 1–6 MCQs',c.first,'310 Mock A–D questions, 32 Studio originals and 258 new questions; 100 per week.'],['banks/weeks-7-14','Weeks 7–14 MCQs',c.second,'50 questions per week: 200 code traces and 200 conceptual questions.'],['code','Guided code exercises',c.guided,'Complete a missing line and study a worked solution.'],['debugging','Debugging exercises',c.debug,'Faulty programs, hints, verified repairs, and regression checks.'],['programs/course','Course program studies',c.course,'62 Mock A–D programs, 10 Week 6 examples and 128 original studies across Weeks 1–14.'],['readings','Reading examples',c.reading,'320 Wang collection examples and 80 Guttag-aligned companions.']];paint(`<div class="intro"><span class="eyebrow">COURSE GUIDE · ENG 101 · FALL 2026</span><h1>Programming for Engineers.</h1><p>A practice companion to the 6 ECTS course, covering foundations, the second half of the semester, and selected reading extensions.</p><p>Instructor: Prof. Yanwei Wang</p></div><div class="guide-grid"><section class="panel"><h2>Course assessment</h2><table class="assessment-table"><caption class="skip">Course assessment weighting</caption><thead><tr><th scope="col">Assessment</th><th scope="col">Weight</th></tr></thead><tbody>${[['Assignments','10%'],['Lab tasks','20%'],['Midterm','30%'],['Final exam','40%']].map(([label,value])=>`<tr><th scope="row">${label}</th><td><strong>${value}</strong></td></tr>`).join('')}</tbody></table><div class="callout"><p>Activities in this studio are ungraded practice. Use Moodle and course announcements for deadlines, submissions, and assessment instructions.</p></div></section><section class="panel"><h2>A useful practice routine</h2><ol><li><strong>Choose.</strong> Open the practice sets for your semester half or focus on one topic.</li><li><strong>Predict.</strong> Trace the program before checking an answer or output.</li><li><strong>Explain.</strong> Read why the answer works, then change one input and predict again.</li><li><strong>Write and repair.</strong> Use the code and debugging labs to apply the idea.</li><li><strong>Revisit.</strong> Return to missed activities through My session.</li></ol><a class="primary" href="#banks">Choose a practice set →</a></section><section class="panel guide-wide"><h2>Scope of this practice space</h2><p>${c.total} distinct practice activities are available across the collections below.</p><div class="table-scroll"><table class="scope-table"><caption class="skip">Practice collections and coverage</caption><thead><tr><th scope="col">Collection</th><th scope="col">Activities</th><th scope="col">What it includes</th></tr></thead><tbody>${scope.map(([page,name,count,description])=>`<tr><th scope="row"><a class="inline-link" href="#${page}">${name}</a></th><td>${count}</td><td>${description}</td></tr>`).join('')}</tbody></table></div><h3>Weeks 1–6 · Foundations</h3><p>Variables and types; arithmetic and units; strings; branches and loops; guess-and-check and bisection; functions and decomposition; tuples, lists and mutation; recursion and dictionaries.</p><h3>Weeks 7–14 · Building further</h3><p>Week 7: testing and debugging. Week 8: object-oriented programming. Week 9: classes, information hiding and inheritance. Weeks 10–11: program efficiency. Week 12: searching and sorting. Week 13: Python, MATLAB, C++ and Java comparisons. Week 14: integrated course review.</p><h3>Weekly slides and notes</h3><p><a class="inline-link" href="#materials">Course materials</a> provides the lecture slides and detailed reading notes for all 14 weeks: 28 PDFs with an optional ZIP bundle for each week.</p><h3>Reading and engineering extensions</h3><p>The reading collection spans all sixteen chapters of the Wang course manuscript, including plotting, files and measurements, matrices, numerical methods, simulation, design projects, and objects. The 80 original Guttag-aligned companion programs identify their chapters and label optional extensions.</p><p>The Program studies library combines ${c.course} course programs with the same ${c.reading} reading examples (${c.allPrograms} programs in total). Reading examples appear in both browsing views and count once toward the activity total.</p></section><section class="panel"><h2>Use the practice tools</h2><p><strong>MCQs:</strong> choose an answer, then study the immediate explanation. Start each question from its printed code and apply only the changes it states.</p><p><strong>Code and debugging labs:</strong> the guided checks compare your work with verified repairs. Run the program and regression checks in your Python environment when exploring another valid approach.</p><p><strong>Program and reading studies:</strong> predict the printed output, check it, then copy or download the program to experiment. Reading examples list any extra package requirements.</p><p>Python 3.10 or later is assumed. Engineering limits and model values are illustrative teaching inputs.</p></section><section class="panel"><h2>Understand your session progress</h2><p>Progress is saved in this browser tab and survives a refresh. First-submission accuracy stays unchanged on retries; latest correctness determines which activities need revisiting. Viewing a solution alone does not count as solving an activity.</p><p>Your session page covers both semester halves, guided exercises, program studies, and debugging. Practice feedback is separate from the course grade.</p><div class="actions"><a class="secondary" href="#session">View my session →</a><a class="text-button" href="https://github.com/ktwyw" target="_blank" rel="noopener noreferrer">Instructor’s GitHub ↗</a></div></section></div>`,'guide');}
function route(){const route=location.hash.slice(1)||'home';if(route==='home')dashboard();else if(route==='practice')home();else if(route==='code')codeHome();else if(route==='second-half'||route==='banks/weeks-7-14')secondHalfHome();else if(route==='banks/weeks-1-6'||route==='first-half')firstHalfHome();else if(route==='banks')banks();else if(route==='materials')materialsHome();else if(route==='readings')readingHome();else if(route==='debugging')debuggingHome();else if(route.startsWith('debug/'))debugExercise(route.split('/')[1]);else if(route==='programs/course'||route==='programs/all'){programFilter=route==='programs/course'?'course':'all';programTopic=programWeek=programProgress='all';programSearch='';programPage=0;programHome();}else if(route==='programs')programHome();else if(route.startsWith('topic/'))topicHome(route.split('/')[1]);else if(route.startsWith('program/')){programDraft='';programStudy(route.split('/')[1]);}else if(route==='session')session();else if(route==='guide')guide();else if(route==='quiz')quiz();else if(route==='summary')summary();else if(route.startsWith('exercise/')){exercise(route.split('/')[1]);}else dashboard();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='skip-content'){main.focus({preventScroll:true});main.scrollIntoView?.({block:'start'});}else if(b.dataset.nav)nav(b.dataset.nav);else if(b.hasAttribute('data-mixed'))mixed();else if(b.dataset.topic)nav('topic/'+b.dataset.topic);else if(b.dataset.topicStart){const t=topicOf(b.dataset.topicStart);const qs=MCQS.filter(q=>q.topic===t.id);startQuiz((b.dataset.sample?sample(qs,10):qs).map(q=>q.id),t.name);}else if(b.dataset.bank){const qs=MCQS.filter(q=>q.bank===b.dataset.bank);startQuiz((b.dataset.sample?sample(qs,10):qs).map(q=>q.id),'Mock '+b.dataset.bank+' practice','banks/weeks-1-6');}else if(b.dataset.programTopic){programFilter='all';programWeek=programProgress='all';programTopic=b.dataset.programTopic;programSearch='';programPage=0;nav('programs');programHome();}else if(b.dataset.program)nav('program/'+b.dataset.program);else if(b.dataset.programQuiz){const p=PROGRAMS.find(p=>p.id===b.dataset.programQuiz);startQuiz(p.questionIds,p.source,'program/'+p.id);}else if(b.dataset.programFilter){programFilter=b.dataset.programFilter;if(['wang','guttag'].includes(programFilter))programWeek='all';programPage=0;if(location.hash!=='#programs')nav('programs');programHome();}else if(b.id==='check-output')checkOutput(b.dataset.id);else if(b.id==='reveal-output'){programDraft=document.getElementById('program-answer').value;if(!state.revealed.includes(b.dataset.id))state.revealed.push(b.dataset.id);save();programStudy(b.dataset.id,'shown');}else if(b.id==='clear-program-filters'){programFilter='course';programTopic=programWeek=programProgress='all';programSearch='';programPage=0;programHome();}else if(b.dataset.exercise){nav('exercise/'+b.dataset.exercise);}else if(b.dataset.filter)codeHome(b.dataset.filter);else if(b.id==='check-answer'&&selected!==null&&!checked){const item=MCQS.find(q=>q.id===run.ids[run.index]);const right=selected===item.answer;record(item,right,'mcq');run.results.push(right);checked=true;quiz();}else if(b.id==='next-question'){if(run.index+1===run.ids.length)nav('summary');else{run.index++;selected=null;checked=false;quiz();}}else if(b.id==='check-code')checkCode(b.dataset.id);else if(b.id==='show-solution'){stashCodeDraft(b.dataset.id);if(!state.revealed.includes(b.dataset.id))state.revealed.push(b.dataset.id);save();exercise(b.dataset.id,'shown');}else if(b.id==='review-missed'){const ids=MCQS.filter(q=>state.records[q.id]&&!state.records[q.id].latestCorrect).map(q=>q.id);if(ids.length)startQuiz(ids,'Revisit missed questions','session');else{const e=EXERCISES.find(x=>state.records[x.id]&&!state.records[x.id].latestCorrect);if(e)nav('exercise/'+e.id);else{const p=PROGRAMS.find(x=>state.records[x.id]&&!state.records[x.id].latestCorrect);if(p)nav('program/'+p.id);else{const d=DEBUG_CASES.find(x=>state.records[x.id]&&!state.records[x.id].latestCorrect);if(d)nav('debug/'+d.id);}}}}else if(b.id==='reset-session')document.getElementById('reset-dialog').showModal();else if(b.id==='cancel-reset')document.getElementById('reset-dialog').close();else if(b.id==='confirm-reset'){state=fresh();save();run=null;document.getElementById('reset-dialog').close();session();}});
document.addEventListener('change',e=>{if(e.target.id==='program-topic'){programTopic=e.target.value;programPage=0;renderProgramList();}else if(e.target.id==='program-week'){programWeek=e.target.value;programPage=0;renderProgramList();}else if(e.target.id==='program-progress'){programProgress=e.target.value;programPage=0;renderProgramList();}else if(e.target.name==='answer'&&!checked){selected=Number(e.target.value);document.getElementById('check-answer').disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='program-search'){programSearch=e.target.value;programPage=0;renderProgramList();}else if(e.target.id==='search'){const value=e.target.value.toLowerCase().trim();const all=TOPICS.filter(t=>(t.name+' '+t.desc).toLowerCase().includes(value));document.getElementById('topic-grid').innerHTML=all.map(topicCard).join('');document.getElementById('no-results').hidden=all.length>0;}});


function sample(items,n){const copy=[...items];for(let i=copy.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]];}return copy.slice(0,n);}
function programCard(p){const rec=state.records[p.id];return `<article class="program-card"><div class="card-top"><span class="tag">${esc(p.source)}</span><span class="tag">${p.reading?`Chapter ${p.chapter}`:`Week ${p.week}`}</span></div><h3>${esc(p.name)}</h3><p>${topicOf(p.topic).name}</p><div class="card-bottom"><span>${rec?.latestCorrect?'✓ Output checked':state.revealed.includes(p.id)?'Output viewed':'Predict · Trace · Check'}</span><button class="text-button" data-program="${p.id}">Open program →</button></div></article>`;}
function topicHome(id){const t=topicOf(id);if(!t){home();return;}const qs=MCQS.filter(q=>q.topic===id);const ps=PROGRAMS.filter(p=>p.topic===id);paint(`<button class="back-button" data-nav="practice">← All topics</button><div class="intro"><span class="eyebrow">TOPIC PRACTICE</span><h1>${t.name}</h1><p>${t.tip}</p></div><section class="panel"><h2>${qs.length} questions, at your pace.</h2><p>Choose a short random round or work through the whole topic. Each question includes its original code and immediate explanation.</p><div class="actions"><button class="primary" data-topic-start="${id}" data-sample="yes">Practise up to 10 questions →</button><button class="secondary" data-topic-start="${id}">All ${qs.length} questions</button></div></section>${ps.length?`<div class="section-heading"><div><h2>Study the programs</h2><p>Predict the output and explore the related questions.</p></div></div><div class="program-grid">${ps.slice(0,6).map(programCard).join('')}</div><button class="secondary" data-program-topic="${id}">Browse all ${ps.length} related programs →</button>`:''}`,'practice');}
function filteredPrograms(){
 const needle=programSearch.toLowerCase().trim();
 return PROGRAMS.filter(p=>{
  const record=state.records[p.id];
  return (programFilter==='all'||programFilter==='course'&&!p.reading||p.bank===programFilter)
   &&(programTopic==='all'||p.topic===programTopic)
   &&(programWeek==='all'||(programWeek==='reading'?!!p.reading:p.week===Number(programWeek)))
   &&(programProgress==='all'||programProgress==='new'&&!record||programProgress==='missed'&&record&&!record.latestCorrect||programProgress==='solved'&&record?.latestCorrect)
   &&(!needle||[p.name,p.id,p.source,topicOf(p.topic).name,p.code].join(' ').toLowerCase().includes(needle));
 }).sort((a,b)=>(a.week??15)-(b.week??15));
}
function nextProgramStudy(id){
 const list=filteredPrograms().filter(p=>!p.reading);
 if(!list.length)return null;
 const index=list.findIndex(p=>p.id===id),next=list[index<0?0:(index+1)%list.length];
 return next.id===id?null:next;
}
function renderProgramList(){
 const list=filteredPrograms();
 programPage=Math.min(programPage,Math.max(0,Math.ceil(list.length/PAGE_SIZE)-1));
 document.getElementById('program-grid').innerHTML=list.length?list.slice(programPage*PAGE_SIZE,(programPage+1)*PAGE_SIZE).map(programCard).join(''):'<p class="empty">No programs match these filters. Try another week, topic, or progress setting.</p>';
 document.getElementById('program-count').textContent=`${list.length} programs`;
 const controls=pageControls(programPage,list.length,'program').replace('examples</span>','programs</span>');
 document.getElementById('program-pagination-top').innerHTML=controls;
 document.getElementById('program-pagination').innerHTML=controls;
}
function programHome(){
 const counts=collectionCounts(),solved=COURSE_PROGRAMS.filter(p=>state.records[p.id]?.latestCorrect).length;
 const sources=[['course',`Course studies · ${counts.course}`],['course-new',`New studies · ${PROGRAM_STUDY_ADDITIONS.length}`],['A','Mock A'],['B','Mock B'],['C','Mock C'],['D','Mock D'],['lecture','Week 6 examples'],['all',`Full library · ${counts.allPrograms}`],['wang','Wang reading'],['guttag','Guttag companions']];
 paint(`<div class="intro"><span class="eyebrow">PROGRAM STUDIES · WEEKS 1–14</span><h1>Trace the code. Explain the result.</h1><p>${counts.course} course program studies, from Python foundations to testing, objects, efficiency, searching and sorting, and integrated engineering calculations. Predict the complete output, compare it with the verified result, then modify the program and explain what changes.</p><p class="muted">${solved} / ${counts.course} course outputs checked · ${PROGRAM_STUDY_ADDITIONS.length} new studies · Instructor: Prof. Yanwei Wang</p><div class="actions"><a class="primary" href="downloads/eng101-program-studies.zip" download>Download all ${counts.course} program studies ↓</a><a class="secondary" href="#readings">Explore the ${counts.reading} Reading examples →</a></div><p class="code-info">The ${counts.course} course studies include the earlier 72 programs and ${PROGRAM_STUDY_ADDITIONS.length} original additions. The full library also includes the same ${counts.reading} Reading examples, giving ${counts.allPrograms} distinct programs. Choose a source below to switch collections.</p></div><div class="filter-bar" aria-label="Filter by source">${sources.map(([id,name])=>`<button class="chip ${programFilter===id?'active':''}" data-program-filter="${id}" aria-pressed="${programFilter===id}">${name}</button>`).join('')}</div><div class="program-toolbar"><label class="search"><input id="program-search" type="search" value="${esc(programSearch)}" placeholder="Find a program, concept, or study ID…" aria-label="Find a program"></label><label class="topic-select">Topic <select id="program-topic"><option value="all">All topics</option>${[...TOPICS,...READING_TOPICS].map(t=>`<option value="${t.id}" ${programTopic===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="topic-select">Week <select id="program-week"><option value="all">All weeks / chapters</option>${Array.from({length:14},(_,i)=>i+1).map(w=>`<option value="${w}" ${programWeek===String(w)?'selected':''}>Week ${w}</option>`).join('')}<option value="reading" ${programWeek==='reading'?'selected':''}>Reading chapters</option></select></label><label class="topic-select">Progress <select id="program-progress">${[['all','All progress'],['new','Not attempted'],['missed','Needs another try'],['solved','Output checked']].map(([value,label])=>`<option value="${value}" ${programProgress===value?'selected':''}>${label}</option>`).join('')}</select></label><button class="text-button" id="clear-program-filters">Reset to course studies</button><span class="muted" id="program-count" role="status"></span></div><div id="program-pagination-top"></div><div class="program-grid" id="program-grid"></div><div id="program-pagination"></div><section class="panel reading-note"><h2>Predict, check, then experiment.</h2><p>All 200 course reference outputs have been checked by running the complete programs in Python. The new studies include explanations, a modification prompt, and selected regression assertions. The download includes the worked programs, reference outputs, and a catalog.</p><p>The browser compares your predicted text with the reference; it does not execute Python. Viewing an output alone does not mark the study as solved. The new programs use the Python standard library. Week 13 comparisons execute Python demonstrations, with native-language execution unverified.</p></section>`,'programs');
 renderProgramList();
}
function normalizeOutput(value){return String(value).replace(/\r\n?/g,'\n').split('\n').map(l=>l.replace(/[ \t]+$/,'')).join('\n').replace(/\n+$/,'');}
function programStudy(id,feedback=null){const p=PROGRAMS.find(p=>p.id===id);if(!p){programHome();return;}const shown=feedback==='shown'||feedback==='right',next=p.reading?null:nextProgramStudy(p.id);paint(`<button class="back-button" data-nav="${p.reading?'readings':'programs'}">← ${p.reading?'Reading examples':'Program studies'}</button><div class="question-layout"><section class="question-card"><div class="question-label"><span>${esc(p.source)}</span><span>${p.reading?`CHAPTER ${p.chapter}`:`WEEK ${p.week}`}</span></div><h1>${esc(p.name)}</h1>${p.note?`<p class="code-info">${esc(p.note)}</p>`:''}${p.requirements?.length?`<p class="dependency-note">Requires: ${p.requirements.map(esc).join(', ')}</p>`:''}<div class="code-tools"><button class="text-button" id="copy-program" data-id="${p.id}">Copy code</button><button class="text-button" id="download-program" data-id="${p.id}">Download .py ↓</button><span id="copy-status" role="status"></span></div><pre><code>${esc(p.code)}</code></pre><label class="field-label" for="program-answer">Predict the complete printed output</label><p class="code-info">Enter one printed line per line. Preserve numeric types, container punctuation, and leading spaces. Trailing spaces and final blank lines are ignored.</p><textarea id="program-answer" class="code-input output-input" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="Type your predicted output…">${esc(programDraft)}</textarea><div class="actions"><button class="primary" id="check-output" data-id="${p.id}">Check my prediction →</button><button class="secondary" id="reveal-output" data-id="${p.id}">Show verified output</button></div>${feedback?`<div class="feedback ${feedback==='wrong'?'incorrect':''}" role="status"><h3>${feedback==='right'?'✓ Your output matches.':feedback==='shown'?'Verified Python output':feedback==='empty'?'Write a prediction first.':'Check the trace once more.'}</h3>${shown?`<pre><code>${esc(p.output)}</code></pre>${referenceExtras(p)}<p>This reference output was produced by running the displayed program in Python. Trace each assignment, branch, function call, and print to explain how it was produced.</p>${feedback==='shown'?'<p>Viewing the output does not mark this program as solved.</p>':''}`:feedback==='wrong'?'<p>Check line order, values, spaces, and the distinction between 4 and 4.0. Lists, tuples, and dictionaries retain their printed punctuation.</p>':'<p>Trace the program and enter the output before checking.</p>'}</div>`:''}${p.reading?`<details class="hint"><summary>Reading reference and modification prompt</summary><p>${esc(p.readingLabel)} · Chapter ${p.chapter}: ${esc(p.chapterTitle)}</p><p>${esc(p.tryIt)}</p><p class="code-info">${esc(p.origin)}</p></details>`:''}<p class="code-info">This output check compares text; it does not execute code in your browser. Copy the program into your Python environment to explore modifications.</p>${p.questionIds.length?`<section class="callout"><h3>Now test your understanding</h3><p>Five earlier MCQs explore this program, including carefully stated modifications.</p><button class="primary" data-program-quiz="${p.id}">Practise the ${p.questionIds.length} questions →</button></section>`:''}${EXERCISES.some(e=>e.program===p.id)?`<p><a class="text-button" href="#exercise/${EXERCISES.find(e=>e.program===p.id).id}">Complete a guided line from this example →</a></p>`:''}${!p.reading?`<div class="actions code-next-actions">${next?`<button class="primary" data-program="${next.id}">Next matching study →</button>`:''}<button class="secondary" data-nav="programs">Back to Program studies</button></div>`:''}</section><aside><div class="tip-panel"><h3>A useful tracing routine</h3><ol><li>List the initial values.</li><li>Follow the execution order.</li><li>Track local variables separately.</li><li>Write only what print displays.</li></ol><p>${topicOf(p.topic).tip}</p></div></aside></div>`,p.reading?'readings':'programs',!feedback);}
function checkOutput(id){const p=PROGRAMS.find(p=>p.id===id);programDraft=document.getElementById('program-answer').value;if(!programDraft.trim()){programStudy(id,'empty');return;}const right=normalizeOutput(programDraft)===normalizeOutput(p.output);record(p,right,'program');programStudy(id,right?'right':'wrong');}
window.addEventListener('hashchange',route);route();
